def merge_windows(windows):
    """Merge an iterable of (start, end) minute windows into sorted,
    disjoint tuples, fusing overlapping and touching intervals.

    Zero-length intervals are dropped. Invalid pairs (non-integers or
    pairs violating 0 <= start <= end <= 1440) raise ValueError.
    Inputs are not mutated.
    """
    collected = []
    for window in windows:
        try:
            start, end = window
        except (TypeError, ValueError):
            raise ValueError('window must be a (start, end) pair: %r'
                             % (window,))
        if not (isinstance(start, int) and isinstance(end, int)):
            raise ValueError('window bounds must be integers: %r' % (window,))
        if not 0 <= start <= end <= 1440:
            raise ValueError('window out of range: %r' % (window,))
        if start == end:
            continue
        collected.append((start, end))

    collected.sort()
    merged = []
    for start, end in collected:
        if not merged or start > merged[-1][1]:
            merged.append((start, end))
        elif end > merged[-1][1]:
            merged[-1] = (merged[-1][0], end)
    return merged

