from times import parse_time
from windows import merge_windows


def free_minutes(lines):
    """Compute busy and free minutes for a schedule of START-END lines.

    Each line must be exactly two times (ASCII HH:MM each) joined by a
    single '-'. Returns {'busy': merged sorted windows, 'free': remaining
    minutes of the day}.
    """
    windows = []
    for line in lines:
        if not isinstance(line, str):
            raise ValueError('schedule line must be a str: %r' % (line,))
        parts = line.split('-')
        if len(parts) != 2:
            raise ValueError('expected exactly START-END: %r' % (line,))
        start = parse_time(parts[0])
        end = parse_time(parts[1])
        if start > end:
            raise ValueError('backwards interval: %r' % (line,))
        windows.append((start, end))

    busy = merge_windows(windows)
    free = 1440 - sum(end - start for start, end in busy)
    return {'busy': busy, 'free': free}

