import unittest

from planner import free_minutes
from times import parse_time
from windows import merge_windows


class Smoke(unittest.TestCase):
    def test_import(self):
        import times, windows, planner


class ParseTimeTests(unittest.TestCase):
    def test_valid_times(self):
        self.assertEqual(parse_time('00:00'), 0)
        self.assertEqual(parse_time('00:01'), 1)
        self.assertEqual(parse_time('12:34'), 12 * 60 + 34)
        self.assertEqual(parse_time('23:59'), 1439)
        self.assertEqual(parse_time('24:00'), 1440)

    def test_invalid_times_raise_valueerror(self):
        for bad in ('24:01', '24:30', '25:00', '09:60', '99:99',
                    '9:00', '09:0', '00', '0900', '', ':', '0:0:0',
                    '-01:00', ' 09:00', '09:00 ', '09:00\n',
                    '09.00', '09-00', '1:00', '000:00'):
            with self.assertRaises(ValueError, msg=bad):
                parse_time(bad)

    def test_non_ascii_digits_rejected(self):
        for bad in ('０９:００', '09:００', '09 ： 00'):
            with self.assertRaises(ValueError, msg=bad):
                parse_time(bad)

    def test_non_string_rejected(self):
        for bad in (None, 900, 9.0, b'09:00', ['09:00']):
            with self.assertRaises(ValueError, msg=repr(bad)):
                parse_time(bad)


class MergeWindowsTests(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(merge_windows([]), [])
        self.assertEqual(merge_windows(iter([])), [])

    def test_sorted_when_input_unsorted(self):
        self.assertEqual(merge_windows([(120, 180), (0, 60)]),
                         [(0, 60), (120, 180)])

    def test_overlap_merged(self):
        self.assertEqual(merge_windows([(0, 60), (30, 90)]), [(0, 90)])

    def test_touching_merged(self):
        self.assertEqual(merge_windows([(0, 60), (60, 120)]), [(0, 120)])
        self.assertEqual(merge_windows([(0, 60), (60, 60), (60, 120)]),
                         [(0, 120)])

    def test_contained_window_swallowed(self):
        self.assertEqual(merge_windows([(0, 120), (30, 60)]), [(0, 120)])

    def test_zero_length_dropped(self):
        self.assertEqual(merge_windows([(0, 0)]), [])
        self.assertEqual(merge_windows([(0, 0), (60, 60)]), [])
        self.assertEqual(merge_windows([(0, 60), (60, 60)]), [(0, 60)])

    def test_full_day(self):
        self.assertEqual(merge_windows([(0, 1440)]), [(0, 1440)])

    def test_input_not_mutated(self):
        windows = [(0, 60), (30, 90), (90, 120)]
        snapshot = list(windows)
        merge_windows(windows)
        self.assertEqual(windows, snapshot)
        self.assertIs(windows[0], snapshot[0])

    def test_generator_input(self):
        gen = ((s, s + 30) for s in (0, 15, 200))
        self.assertEqual(merge_windows(gen), [(0, 45), (200, 230)])

    def test_invalid_pairs_raise_valueerror(self):
        for bad in [(-1, 60), (0, 1441), (61, 60), (120, 1000),
                    (1440, 1440), (1441, 1440), (0.0, 60), (0, 60.5),
                    (1,), (), (0, 60, 120), 42, '09:00',
                    (None, 60), ('0', '60')]:
            with self.assertRaises(ValueError, msg=repr(bad)):
                merge_windows([bad])

    def test_partial_iteration_still_validates(self):
        def gen():
            yield (0, 60)
            yield (-5, 10)

        with self.assertRaises(ValueError):
            merge_windows(gen())


class FreeMinutesTests(unittest.TestCase):
    def test_empty_lines_full_day_free(self):
        self.assertEqual(free_minutes([]), {'busy': [], 'free': 1440})
        self.assertEqual(free_minutes(iter([])), {'busy': [], 'free': 1440})

    def test_single_window(self):
        self.assertEqual(free_minutes(['09:00-17:00']),
                         {'busy': [(540, 1020)], 'free': 960})

    def test_overlap_merged_and_free_deducted_once(self):
        result = free_minutes(['09:00-12:00', '11:00-13:00'])
        self.assertEqual(result['busy'], [(540, 780)])
        self.assertEqual(result['free'], 1440 - (780 - 540))

    def test_touching_merged(self):
        result = free_minutes(['09:00-12:00', '12:00-13:00'])
        self.assertEqual(result['busy'], [(540, 780)])
        self.assertEqual(result['free'], 1440 - 240)

    def test_unsorted_lines_sorted_result(self):
        result = free_minutes(['13:00-14:00', '09:00-10:00'])
        self.assertEqual(result['busy'], [(540, 600), (780, 840)])

    def test_full_day(self):
        self.assertEqual(free_minutes(['00:00-24:00']),
                         {'busy': [(0, 1440)], 'free': 0})

    def test_zero_length_line_keeps_day_free(self):
        self.assertEqual(free_minutes(['00:00-00:00', '12:00-12:00']),
                         {'busy': [], 'free': 1440})

    def test_generator_input(self):
        gen = (line for line in ['09:00-10:00', '10:00-11:00'])
        self.assertEqual(free_minutes(gen),
                         {'busy': [(540, 660)], 'free': 1320})

    def test_invalid_time_raises(self):
        for bad in ('9:00-10:00', '09:00-24:01', '09:00-25:00',
                    'abcd-efgh', '09:00', '09:00-10', '09:00 10:00'):
            with self.assertRaises(ValueError, msg=bad):
                free_minutes([bad])

    def test_backwards_interval_raises(self):
        with self.assertRaises(ValueError):
            free_minutes(['12:00-09:00'])

    def test_extra_separator_raises(self):
        for bad in ('09:00-10:00-', '-09:00-10:00', '09:00--10:00',
                    '09:00-10:00-11:00'):
            with self.assertRaises(ValueError, msg=bad):
                free_minutes([bad])

    def test_non_string_line_raises(self):
        with self.assertRaises(ValueError):
            free_minutes([('09:00', '10:00')])

    def test_input_not_mutated(self):
        lines = ['09:00-12:00', '11:00-13:00']
        snapshot = list(lines)
        free_minutes(lines)
        self.assertEqual(lines, snapshot)

    def test_realistic_day(self):
        lines = ['08:00-08:30', '09:00-10:00', '09:30-11:00',
                 '10:30-12:00', '14:00-15:00', '15:00-16:00']
        result = free_minutes(lines)
        self.assertEqual(result['busy'], [(480, 720), (840, 960)])
        self.assertEqual(result['free'], 1440 - 240 - 120)


if __name__ == '__main__':
    unittest.main()

